if(!isset($params['transfer']->resultData)) {
    $params['response']->headers->set('Content-Type', 'application/json');
    $params['transfer']->resultData = [];
}

$decodeValue = function($value) {
    if(is_string($value) && !is_numeric($value)) {
        $decodedValue = json_decode($value, true);
        if (json_last_error() === \JSON_ERROR_NONE) {
            $value = $decodedValue;
        }
    }

    return $value;
};

if($params['rawItemData']) {
    $item = [];
    $item['ID'] = $decodeValue({{ ID }});
    $item['Key'] = $decodeValue({{ Key }});
    $item['Path'] = $decodeValue({{ Path }});
    $item['Published'] = $decodeValue({{ Published }});
    $item['Name'] = $decodeValue({{ Name }});
    $item['Short Description'] = $decodeValue({{ Short Description }});
    $item['SKU'] = $decodeValue({{ SKU }});
    $item['Brand'] = $decodeValue({{ Brand }});
    $item['Price'] = $decodeValue({{ Price }});
    $item['Images'] = $decodeValue({{ Images }});

    $params['transfer']->resultData[] = $item;
}

if($params['lastCall']) {
    return json_encode($params['transfer']->resultData, \JSON_UNESCAPED_UNICODE);
}
